cat > /app/output/index.html <<'EOF'
<!doctype html>
<html lang="en">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1.0" />
  <title>MedBook — Find and Book Top Doctors Instantly</title>
  <meta name="description" content="Search thousands of doctors, dentists, and specialists. Read verified reviews. Book appointments instantly — always free for patients." />
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700;800&display=swap" rel="stylesheet">
  <style>
    :root {
      --blue-700: #0066FF;
      --blue-800: #1B1464;
      --teal-500: #17B890;
      --teal-600: #119A79;
      --bg: #ffffff;
      --surface: #f6f9ff;
      --surface-2: #eef4ff;
      --text: #10213e;
      --muted: #5f6f8a;
      --border: #dbe6ff;
      --shadow: 0 14px 42px rgba(10, 34, 88, 0.12);
      --radius-lg: 20px;
      --radius-md: 14px;
      --radius-sm: 10px;
      --max: 1120px;
    }
    * { box-sizing: border-box; }
    html { scroll-behavior: smooth; }
    body {
      margin: 0;
      font-family: Inter, system-ui, -apple-system, Segoe UI, Roboto, sans-serif;
      color: var(--text);
      background: radial-gradient(circle at 8% 0%, #eef4ff 0%, #ffffff 35%) no-repeat;
      line-height: 1.55;
    }
    a { color: inherit; text-decoration: none; }
    .container { width: min(var(--max), 92vw); margin: 0 auto; }

    header {
      position: sticky;
      top: 0;
      z-index: 30;
      backdrop-filter: blur(10px);
      background: rgba(255, 255, 255, 0.9);
      border-bottom: 1px solid rgba(219, 230, 255, 0.75);
    }
    .header-row {
      display: flex;
      align-items: center;
      justify-content: space-between;
      min-height: 76px;
      gap: 20px;
    }
    .logo {
      display: inline-flex;
      align-items: center;
      gap: 10px;
      font-weight: 800;
      font-size: 1.2rem;
      color: var(--blue-800);
    }
    .logo-badge {
      width: 34px;
      height: 34px;
      border-radius: 10px;
      background: linear-gradient(135deg, var(--blue-700), #5b8cff);
      display: grid;
      place-items: center;
      color: #fff;
      font-weight: 800;
      box-shadow: 0 8px 20px rgba(0, 102, 255, 0.3);
    }
    nav.desktop-nav {
      display: flex;
      align-items: center;
      gap: 24px;
      font-weight: 500;
      color: #2e3e5b;
    }
    nav.desktop-nav a:hover { color: var(--blue-700); }
    .btn {
      border: 0;
      border-radius: 999px;
      padding: 12px 18px;
      font-weight: 700;
      cursor: pointer;
      transition: transform .2s ease, box-shadow .2s ease, background .2s ease;
      font-family: inherit;
    }
    .btn:hover { transform: translateY(-1px); }
    .btn-primary {
      background: var(--blue-700);
      color: #fff;
      box-shadow: 0 10px 24px rgba(0, 102, 255, .3);
    }
    .btn-primary:hover { background: #0052cc; }
    .btn-accent {
      background: var(--teal-500);
      color: #fff;
      box-shadow: 0 10px 24px rgba(23, 184, 144, .28);
    }
    .btn-accent:hover { background: var(--teal-600); }
    .menu-toggle {
      display: none;
      background: transparent;
      border: 0;
      font-size: 1.5rem;
      color: var(--blue-800);
      cursor: pointer;
      width: 42px;
      height: 42px;
      border-radius: 10px;
    }
    .menu-toggle:focus-visible { outline: 3px solid #9fc3ff; }

    .mobile-drawer {
      position: fixed;
      top: 0;
      right: -320px;
      width: min(80vw, 320px);
      height: 100vh;
      background: #fff;
      box-shadow: -12px 0 34px rgba(13, 31, 68, 0.2);
      z-index: 40;
      transition: right .28s ease;
      padding: 24px;
      display: flex;
      flex-direction: column;
      gap: 14px;
    }
    .mobile-drawer.open { right: 0; }
    .drawer-overlay {
      position: fixed;
      inset: 0;
      background: rgba(7, 19, 41, .45);
      opacity: 0;
      visibility: hidden;
      transition: .24s ease;
      z-index: 35;
    }
    .drawer-overlay.show { opacity: 1; visibility: visible; }

    .hero { padding: 70px 0 40px; }
    .hero-grid {
      display: grid;
      grid-template-columns: 1.2fr .8fr;
      gap: 34px;
      align-items: start;
    }
    .hero h1 {
      font-size: clamp(2rem, 4.5vw, 3.3rem);
      line-height: 1.05;
      margin: 0 0 14px;
      letter-spacing: -0.02em;
      color: #0e2044;
    }
    .hero p {
      font-size: 1.1rem;
      color: var(--muted);
      margin: 0 0 22px;
      max-width: 64ch;
    }
    .hero-actions { display: flex; gap: 12px; flex-wrap: wrap; }

    .hero-art {
      background: linear-gradient(165deg, #f2f7ff, #ffffff);
      border: 1px solid var(--border);
      border-radius: var(--radius-lg);
      padding: 22px;
      box-shadow: var(--shadow);
    }
    .pill-row { display: flex; gap: 10px; flex-wrap: wrap; margin-bottom: 14px; }
    .pill {
      border-radius: 999px;
      border: 1px solid var(--border);
      background: #fff;
      color: #24446f;
      padding: 8px 12px;
      font-size: .86rem;
      font-weight: 600;
    }
    .appt-card {
      border-radius: 16px;
      padding: 14px;
      background: #fff;
      border: 1px solid var(--border);
      display: grid;
      gap: 10px;
    }
    .appt-top { display: flex; justify-content: space-between; align-items: center; }
    .avatar {
      width: 40px;
      height: 40px;
      border-radius: 50%;
      background: linear-gradient(180deg, #8fd3ff, #4f83ff);
      display: grid;
      place-items: center;
      color: #fff;
      font-weight: 700;
    }

    .search-wrap { margin-top: 24px; }
    .search-card {
      background: #fff;
      border-radius: 18px;
      border: 1px solid #d8e4ff;
      box-shadow: 0 20px 52px rgba(19, 44, 88, 0.18);
      padding: 14px;
      position: relative;
    }
    .search-form {
      display: grid;
      grid-template-columns: 1.8fr 1.2fr 1.1fr auto;
      gap: 10px;
      align-items: stretch;
    }
    .field {
      background: var(--surface);
      border: 1px solid transparent;
      border-radius: 12px;
      padding: 12px 13px;
      display: grid;
      gap: 6px;
    }
    .field:focus-within {
      border-color: #9abfff;
      background: #fff;
      box-shadow: 0 0 0 3px rgba(0, 102, 255, .12);
    }
    .field label {
      font-size: .76rem;
      color: #557097;
      font-weight: 700;
      text-transform: uppercase;
      letter-spacing: .03em;
    }
    .field input, .field select {
      width: 100%;
      border: 0;
      background: transparent;
      font: inherit;
      color: #10213e;
      outline: none;
      padding: 0;
      min-height: 24px;
    }
    .autocomplete { position: relative; }
    .suggestions {
      position: absolute;
      top: calc(100% + 8px);
      left: 0;
      right: 0;
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 12px;
      box-shadow: 0 16px 36px rgba(11, 38, 85, .17);
      overflow: hidden;
      display: none;
      z-index: 15;
      max-height: 260px;
      overflow-y: auto;
    }
    .suggestions.show { display: block; }
    .suggestion-item {
      padding: 11px 12px;
      cursor: pointer;
      font-weight: 500;
    }
    .suggestion-item:hover, .suggestion-item.active {
      background: var(--surface-2);
      color: var(--blue-700);
    }

    section { padding: 58px 0; }
    .section-head { margin-bottom: 20px; }
    .section-head h2 {
      font-size: clamp(1.45rem, 3vw, 2rem);
      margin: 0 0 8px;
      letter-spacing: -0.01em;
    }
    .section-head p { margin: 0; color: var(--muted); }

    .stats {
      background: linear-gradient(120deg, #0f2e74, #0066ff);
      color: #fff;
      border-radius: 18px;
      padding: 18px;
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 10px;
      box-shadow: var(--shadow);
    }
    .stat {
      background: rgba(255,255,255,.14);
      border: 1px solid rgba(255,255,255,.2);
      border-radius: 12px;
      padding: 16px 14px;
      text-align: center;
    }
    .stat strong { display: block; font-size: 1.4rem; margin-bottom: 4px; }

    .specialty-grid {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
    }
    .specialty-card {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 16px;
      padding: 16px;
      display: grid;
      gap: 8px;
      transition: transform .2s ease, box-shadow .2s ease, border-color .2s ease;
      box-shadow: 0 6px 20px rgba(12, 34, 78, .06);
      cursor: pointer;
    }
    .specialty-card:hover {
      transform: translateY(-3px);
      border-color: #99beff;
      box-shadow: 0 12px 30px rgba(12, 34, 78, .13);
    }
    .icon {
      width: 42px;
      height: 42px;
      border-radius: 12px;
      background: #e8f0ff;
      color: var(--blue-700);
      display: grid;
      place-items: center;
      font-size: 1.2rem;
    }

    .steps {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
    }
    .step {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 16px;
      padding: 18px;
    }
    .step-num {
      width: 34px;
      height: 34px;
      border-radius: 10px;
      display: grid;
      place-items: center;
      font-weight: 800;
      color: #fff;
      background: linear-gradient(150deg, #2f7dff, #17b890);
      margin-bottom: 10px;
    }

    .testimonials {
      display: grid;
      grid-template-columns: repeat(3, 1fr);
      gap: 14px;
    }
    .quote {
      background: #fff;
      border: 1px solid var(--border);
      border-radius: 16px;
      padding: 18px;
      box-shadow: 0 10px 26px rgba(11, 34, 82, .08);
    }

    .app-promo {
      background: linear-gradient(145deg, #f4f8ff, #ecfff9);
      border: 1px solid var(--border);
      border-radius: 18px;
      padding: 26px;
      display: grid;
      grid-template-columns: 1.3fr .7fr;
      gap: 18px;
      align-items: center;
    }
    .feature-list { display: grid; gap: 6px; color: #355077; }
    .store-buttons { display: grid; gap: 10px; }

    footer {
      margin-top: 26px;
      background: #0e1f44;
      color: #dbe6ff;
      padding: 42px 0 24px;
    }
    .footer-grid {
      display: grid;
      grid-template-columns: repeat(4, 1fr);
      gap: 16px;
    }
    .footer-col h4 { margin: 0 0 10px; color: #fff; }
    .footer-col a { display: block; margin-bottom: 8px; color: #d0ddff; font-size: .95rem; }
    .footer-col a:hover { color: #fff; }
    .copy { margin-top: 20px; border-top: 1px solid rgba(173, 192, 240, .25); padding-top: 14px; font-size: .92rem; }

    @media (max-width: 980px) {
      .hero-grid,
      .app-promo { grid-template-columns: 1fr; }
      .search-form { grid-template-columns: 1fr 1fr; }
      .stats { grid-template-columns: 1fr 1fr; }
      .specialty-grid,
      .steps,
      .testimonials,
      .footer-grid { grid-template-columns: 1fr 1fr; }
    }
    @media (max-width: 760px) {
      nav.desktop-nav { display: none; }
      .menu-toggle { display: inline-grid; place-items: center; }
      .hero { padding-top: 34px; }
      .search-form { grid-template-columns: 1fr; }
      .stats,
      .specialty-grid,
      .steps,
      .testimonials,
      .footer-grid { grid-template-columns: 1fr; }
      .btn { width: 100%; }
      .hero-actions .btn { width: auto; }
    }
  </style>
</head>
<body>
  <header>
    <div class="container header-row">
      <a href="index.html" class="logo" aria-label="MedBook home">
        <span class="logo-badge">M</span>
        <span>MedBook</span>
      </a>

      <nav class="desktop-nav" aria-label="Main navigation">
        <a href="#specialties">Browse</a>
        <a href="#footer">Help</a>
        <a href="#">Log In</a>
        <button class="btn btn-primary" type="button">Sign Up</button>
      </nav>

      <button class="menu-toggle" id="menuToggle" aria-label="Open menu" aria-expanded="false" aria-controls="mobileDrawer">☰</button>
    </div>
  </header>

  <div class="drawer-overlay" id="drawerOverlay"></div>
  <aside class="mobile-drawer" id="mobileDrawer" aria-label="Mobile menu">
    <button class="btn" id="closeDrawer" type="button" style="align-self:flex-end; padding:8px 12px;">✕</button>
    <a href="#specialties">Browse</a>
    <a href="#">Log In</a>
    <a href="#" class="btn btn-primary" style="text-align:center;">Sign Up</a>
  </aside>

  <main>
    <section class="hero container" id="hero">
      <div class="hero-grid">
        <div>
          <h1>Find and book the care you need</h1>
          <p>Search thousands of doctors, dentists, and specialists. Read verified patient reviews. Book appointments instantly — even same-day. It's that easy, and always free.</p>
          <div class="hero-actions">
            <button class="btn btn-primary" type="button">Find a Doctor</button>
            <a href="#search-panel" class="btn btn-accent">Search</a>
          </div>

          <div class="search-wrap" id="search-panel">
            <div class="search-card">
              <form class="search-form" id="searchForm" action="search-results.html" method="get">
                <div class="field autocomplete">
                  <label for="query">Specialty / Condition / Doctor</label>
                  <input id="query" name="query" type="text" placeholder="Search by condition, specialty, or doctor name" autocomplete="off" aria-autocomplete="list" aria-controls="suggestions" />
                  <div class="suggestions" id="suggestions" role="listbox" aria-label="Search suggestions"></div>
                </div>

                <div class="field">
                  <label for="location">Location</label>
                  <input id="location" name="location" type="text" placeholder="City, state, or zip code" />
                </div>

                <div class="field">
                  <label for="insurance">Insurance</label>
                  <select id="insurance" name="insurance">
                    <option value="">Choose your insurance plan</option>
                    <option>Aetna</option>
                    <option>Blue Cross</option>
                    <option>Cigna</option>
                    <option>UnitedHealthcare</option>
                    <option>Kaiser Permanente</option>
                    <option>Humana</option>
                  </select>
                </div>

                <button class="btn btn-accent" type="submit" aria-label="Search doctors">Search</button>
              </form>
            </div>
          </div>
        </div>

        <div class="hero-art" aria-hidden="true">
          <div class="pill-row">
            <span class="pill">✔ Same-day visits</span>
            <span class="pill">✔ Verified reviews</span>
            <span class="pill">✔ Free for patients</span>
          </div>
          <div class="appt-card">
            <div class="appt-top">
              <div style="display:flex; gap:10px; align-items:center;">
                <div class="avatar">SC</div>
                <div>
                  <strong>Dr. Sarah Chen</strong>
                  <div style="color:#58729a; font-size:.9rem;">Dermatologist · 4.9 ★</div>
                </div>
              </div>
              <span class="pill" style="margin:0;">Today</span>
            </div>
            <div style="display:flex; gap:8px; flex-wrap:wrap;">
              <span class="pill">10:30 AM</span>
              <span class="pill">12:15 PM</span>
              <span class="pill">2:00 PM</span>
            </div>
          </div>
        </div>
      </div>
    </section>

    <section class="container" aria-label="Platform statistics">
      <div class="stats">
        <div class="stat"><strong>4.8M+</strong><span>Verified patient reviews</span></div>
        <div class="stat"><strong>12,000+</strong><span>Healthcare providers nationwide</span></div>
        <div class="stat"><strong>Same-day</strong><span>Appointments available daily</span></div>
        <div class="stat"><strong>100% free</strong><span>For patients — always</span></div>
      </div>
    </section>

    <section class="container" id="specialties">
      <div class="section-head">
        <h2>Popular specialties</h2>
        <p>Browse common care needs and jump straight to filtered results.</p>
      </div>
      <div class="specialty-grid" id="specialtyCards">
        <article class="specialty-card" data-specialty="Primary Care"><div class="icon">🩺</div><strong>Primary Care</strong><span>Annual checkups, sick visits, and preventive care</span></article>
        <article class="specialty-card" data-specialty="Dentist"><div class="icon">🦷</div><strong>Dentist</strong><span>Cleanings, fillings, and oral health exams</span></article>
        <article class="specialty-card" data-specialty="Dermatologist"><div class="icon">✨</div><strong>Dermatologist</strong><span>Skin conditions, acne, and cosmetic consultations</span></article>
        <article class="specialty-card" data-specialty="Psychiatrist"><div class="icon">🧠</div><strong>Psychiatrist</strong><span>Mental health evaluations and medication management</span></article>
        <article class="specialty-card" data-specialty="Eye Doctor"><div class="icon">👁️</div><strong>Eye Doctor</strong><span>Vision exams, glasses prescriptions, and eye health</span></article>
        <article class="specialty-card" data-specialty="Orthopedic Surgeon"><div class="icon">🦴</div><strong>Orthopedic Surgeon</strong><span>Joint pain, fractures, and sports injuries</span></article>
      </div>
    </section>

    <section class="container">
      <div class="section-head">
        <h2>How it works</h2>
        <p>Book in minutes with a clear three-step flow.</p>
      </div>
      <div class="steps">
        <article class="step"><div class="step-num">1</div><strong>Search for a provider</strong><p>Enter your specialty, condition, or doctor name with location and insurance. Browse profiles with credentials and office hours.</p></article>
        <article class="step"><div class="step-num">2</div><strong>Choose a time that works for you</strong><p>View real-time availability and pick a slot that fits your schedule, including same-day and next-day appointments.</p></article>
        <article class="step"><div class="step-num">3</div><strong>Book your appointment instantly</strong><p>Confirm your visit in a few clicks and get instant confirmation plus reminders so you never miss an appointment.</p></article>
      </div>
    </section>

    <section class="container">
      <div class="section-head">
        <h2>What patients are saying</h2>
        <p>Real stories from people who found care quickly.</p>
      </div>
      <div class="testimonials">
        <article class="quote"><p>“I found a great dermatologist near my office and booked a same-day appointment during my lunch break. MedBook made it incredibly easy.”</p><strong>Priya M., New York, NY</strong></article>
        <article class="quote"><p>“As someone new to the city, MedBook helped me find a primary care doctor who accepts my insurance in under five minutes. Highly recommend!”</p><strong>James T., Chicago, IL</strong></article>
        <article class="quote"><p>“I was dreading finding a new dentist, but the verified reviews on MedBook gave me confidence. My appointment was exactly what I needed.”</p><strong>Laura K., Austin, TX</strong></article>
      </div>
    </section>

    <section class="container">
      <div class="app-promo">
        <div>
          <h2 style="margin-top:0;">Your health, in your pocket</h2>
          <p style="color:var(--muted);">Download the MedBook app to search for doctors, manage appointments, and get reminders — all on the go. Available on iOS and Android.</p>
          <div class="feature-list">
            <span>• Book and manage appointments anywhere</span>
            <span>• Get real-time appointment reminders</span>
            <span>• Access your visit history and provider details</span>
            <span>• Read and leave verified reviews</span>
          </div>
        </div>
        <div class="store-buttons">
          <button class="btn btn-primary" type="button">Download on the App Store</button>
          <button class="btn btn-accent" type="button">Get it on Google Play</button>
        </div>
      </div>
    </section>
  </main>

  <footer id="footer">
    <div class="container">
      <div class="footer-grid">
        <div class="footer-col"><h4>For Patients</h4><a href="#">Find a Doctor</a><a href="#">Browse Specialties</a><a href="#">Read Reviews</a><a href="#">Insurance Guide</a></div>
        <div class="footer-col"><h4>For Providers</h4><a href="#">List Your Practice</a><a href="#">Provider Resources</a><a href="#">Advertise with Us</a></div>
        <div class="footer-col"><h4>Company</h4><a href="#">About MedBook</a><a href="#">Careers</a><a href="#">Press</a><a href="#">Blog</a><a href="#">Contact Us</a></div>
        <div class="footer-col"><h4>Legal</h4><a href="#">Terms of Service</a><a href="#">Privacy Policy</a><a href="#">Accessibility</a><a href="#">Do Not Sell My Info</a></div>
      </div>
      <div class="copy">© 2024 MedBook, Inc. All rights reserved. MedBook is free for patients. Always.</div>
    </div>
  </footer>

  <script>
    const menuToggle = document.getElementById('menuToggle');
    const mobileDrawer = document.getElementById('mobileDrawer');
    const drawerOverlay = document.getElementById('drawerOverlay');
    const closeDrawer = document.getElementById('closeDrawer');

    const openDrawer = () => {
      mobileDrawer.classList.add('open');
      drawerOverlay.classList.add('show');
      menuToggle.setAttribute('aria-expanded', 'true');
    };

    const closeMenu = () => {
      mobileDrawer.classList.remove('open');
      drawerOverlay.classList.remove('show');
      menuToggle.setAttribute('aria-expanded', 'false');
    };

    menuToggle.addEventListener('click', openDrawer);
    closeDrawer.addEventListener('click', closeMenu);
    drawerOverlay.addEventListener('click', closeMenu);

    const suggestionsData = [
      'Dentist', 'Back pain', 'Dr. Sarah Chen', 'Primary Care', 'Dermatologist', 'Psychiatrist', 'Eye Doctor', 'Orthopedic Surgeon', 'Anxiety', 'Migraine'
    ];

    const queryInput = document.getElementById('query');
    const suggestionsEl = document.getElementById('suggestions');
    let activeIndex = -1;

    function renderSuggestions(value) {
      const normalized = value.trim().toLowerCase();
      if (!normalized) {
        suggestionsEl.classList.remove('show');
        suggestionsEl.innerHTML = '';
        activeIndex = -1;
        return;
      }

      const filtered = suggestionsData.filter((item) => item.toLowerCase().includes(normalized)).slice(0, 8);
      if (!filtered.length) {
        suggestionsEl.classList.remove('show');
        suggestionsEl.innerHTML = '';
        activeIndex = -1;
        return;
      }

      suggestionsEl.innerHTML = filtered.map((item, index) => `<div class="suggestion-item" role="option" data-index="${index}">${item}</div>`).join('');
      suggestionsEl.classList.add('show');
      activeIndex = -1;

      [...suggestionsEl.querySelectorAll('.suggestion-item')].forEach((element) => {
        element.addEventListener('mousedown', (event) => {
          event.preventDefault();
          queryInput.value = element.textContent;
          suggestionsEl.classList.remove('show');
        });
      });
    }

    queryInput.addEventListener('input', (event) => renderSuggestions(event.target.value));

