      drawerOverlay.classList.add('show');
      menuToggle.setAttribute('aria-expanded', 'true');
    };

    const closeMenu = () => {
      mobileDrawer.classList.remove('open');
      drawerOverlay.classList.remove('show');
      menuToggle.setAttribute('aria-expanded', 'false');
    };

    menuToggle.addEventListener('click', openDrawer);
    closeDrawer.addEventListener('click', closeMenu);
    drawerOverlay.addEventListener('click', closeMenu);

    const suggestionsData = [
      'Dentist', 'Back pain', 'Dr. Sarah Chen', 'Primary Care', 'Dermatologist', 'Psychiatrist', 'Eye Doctor', 'Orthopedic Surgeon', 'Anxiety', 'Migraine'
    ];

    const queryInput = document.getElementById('query');
    const suggestionsEl = document.getElementById('suggestions');
    let activeIndex = -1;

    function renderSuggestions(value) {
      const normalized = value.trim().toLowerCase();
      if (!normalized) {
        suggestionsEl.classList.remove('show');
        suggestionsEl.innerHTML = '';
        activeIndex = -1;
        return;
      }

      const filtered = suggestionsData.filter((item) => item.toLowerCase().includes(normalized)).slice(0, 8);
      if (!filtered.length) {
        suggestionsEl.classList.remove('show');
        suggestionsEl.innerHTML = '';
        activeIndex = -1;
        return;
      }

      suggestionsEl.innerHTML = filtered.map((item, index) => `<div class="suggestion-item" role="option" data-index="${index}">${item}</div>`).join('');
      suggestionsEl.classList.add('show');
      activeIndex = -1;

      [...suggestionsEl.querySelectorAll('.suggestion-item')].forEach((element) => {
        element.addEventListener('mousedown', (event) => {
          event.preventDefault();
          queryInput.value = element.textContent;
          suggestionsEl.classList.remove('show');
        });
      });
    }

    queryInput.addEventListener('input', (event) => renderSuggestions(event.target.value));

    queryInput.addEventListener('keydown', (event) => {
      const items = [...suggestionsEl.querySelectorAll('.suggestion-item')];
      if (!items.length) return;

      if (event.key === 'ArrowDown') {
        event.preventDefault();
        activeIndex = (activeIndex + 1) % items.length;
      } else if (event.key === 'ArrowUp') {
        event.preventDefault();
        activeIndex = (activeIndex - 1 + items.length) % items.length;
      } else if (event.key === 'Enter' && activeIndex >= 0) {
        event.preventDefault();
        queryInput.value = items[activeIndex].textContent;
        suggestionsEl.classList.remove('show');
      } else if (event.key === 'Escape') {
        suggestionsEl.classList.remove('show');
      }

      items.forEach((item, index) => item.classList.toggle('active', index === activeIndex));
    });

    document.addEventListener('click', (event) => {
      if (!event.target.closest('.autocomplete')) {
        suggestionsEl.classList.remove('show');
      }
    });

    const locationInput = document.getElementById('location');
    locationInput.addEventListener('focus', () => {
      if (!locationInput.value && navigator.geolocation) {
        locationInput.placeholder = 'Use current location (allow access)';
      }
    });

    document.getElementById('searchForm').addEventListener('submit', (event) => {
      event.preventDefault();
      const params = new URLSearchParams(new FormData(event.target));
      window.location.href = `search-results.html?${params.toString()}`;
    });

    document.querySelectorAll('.specialty-card').forEach((card) => {
      card.addEventListener('click', () => {
        const specialty = card.getAttribute('data-specialty');
        window.location.href = `search-results.html?query=${encodeURIComponent(specialty)}`;
      });
    });
  </script>
</body>
